const spreadsheetId = "YOUR_SPREADSHEET_ID",
  sheetName = "Sheet1";
if (!spreadsheetId || spreadsheetId.startsWith("YOUR_") || !sheetName.trim())
  throw Error("Configure spreadsheet and sheet");
return [
  { json: { spreadsheetId, sheetName, range: "'" + sheetName.replace(/'/g, "''") + "'!A:Z" } },
];

function prepare({ values }) {
  if (!Array.isArray(values) || !Array.isArray(values[0]))
    throw Error("Sheet must have a header row");
  const names = [
      "domain",
      "name",
      "description",
      "processed_at",
      "data",
      "domain_name",
      "traffic",
      "location",
      "funds",
      "year_founded",
      "funding_round",
      "last_funding_at",
    ],
    header = values[0],
    columns = {};
  for (const name of names) {
    let indices = header.flatMap((v, i) => (v === name ? [i] : []));
    if (indices.length !== 1) throw Error("Expected one " + name + " column");
    columns[name] = indices[0];
  }
  const rows = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!Array.isArray(row)) throw Error("Invalid sheet row");
    const processed = row[columns.processed_at];
    if (processed !== undefined && processed !== null && processed !== "") continue;
    const domain = row[columns.domain];
    if (typeof domain !== "string" || !domain.trim()) continue;
    rows.push({ row: i + 1, domain: domain.trim() });
  }
  return { rows, columns };
}

const x = prepare({ values: $input.first().json.values ?? [] });
return x.rows.map((row, i) => ({ json: { row, columns: x.columns }, pairedItem: { item: 0 } }));

function map({ row, columns, response, sheetName }) {
  if (
    !response ||
    typeof response !== "object" ||
    !response.data ||
    typeof response.data !== "object"
  )
    throw Error("ProspectLens response missing data");
  const d = response.data,
    need = (path) => {
      let v = d;
      for (const k of path) {
        if (
          v === null ||
          v === undefined ||
          typeof v !== "object" ||
          !Object.prototype.hasOwnProperty.call(v, k)
        )
          throw Error("ProspectLens response missing " + path.join("."));
        v = v[k];
      }
      if (!["string", "number", "boolean"].includes(typeof v))
        throw Error("Invalid " + path.join("."));
      return v;
    };
  const vals = {
    domain: row.domain,
    name: need(["properties", "title"]),
    description: need(["properties", "short_description"]),
    processed_at: new Date().toISOString(),
    data: JSON.stringify(d).substr(0, 2000),
    domain_name: need(["info", "company_about_fields", "website", "hostname"]),
    traffic: need(["info", "semrush_summary", "semrush_visits_latest_month"]),
    location: need(["info", "semrush_location_list", "0", "location_identifiers", "0", "value"]),
    funds: need(["info", "funding_rounds_summary", "funding_total", "value"]),
    year_founded: need(["info", "overview_fields_extended", "founded_on", "value"]),
    funding_round: need(["info", "funding_rounds_summary", "last_funding_type"]),
    last_funding_at: need(["info", "funding_rounds_summary", "last_funding_at"]),
  };
  if (
    typeof sheetName !== "string" ||
    !sheetName.trim() ||
    !Number.isInteger(row.row) ||
    row.row < 2
  )
    throw Error("Invalid sheet location");
  const name = "'" + sheetName.replace(/'/g, "''") + "'",
    col = (i) => {
      if (!Number.isInteger(i) || i < 0 || i >= 26) throw Error("Column outside A:Z");
      return String.fromCharCode(65 + i);
    };
  const data = Object.entries(vals).map(([key, value]) => ({
    range: `${name}!${col(columns[key])}${row.row}`,
    majorDimension: "ROWS",
    values: [[value]],
  }));
  return { data };
}

const prev = $("Loop Over Items").item.json,
  cfg = $("Choose the sheet").first().json;
return [
  {
    json: map({
      row: prev.row,
      columns: prev.columns,
      response: $input.first().json,
      sheetName: cfg.sheetName,
    }),
  },
];

const x = $input.first().json,
  c = $("Choose the sheet").first().json;
if (x.spreadsheetId !== c.spreadsheetId || x.totalUpdatedCells !== 12)
  throw Error("Sheet update not confirmed");
return [{ json: { ok: true } }];
